import{assayBands}from './special-infection-models.js?v=20261023-physicscomplete01';
const mat=(T,c,e={})=>new T.MeshStandardMaterial({color:c,roughness:.32,metalness:.03,...e});
function ball(g,T,x,y,z,r,c,scale=[1,1,1],name=''){let m=new T.Mesh(new T.SphereGeometry(r,28,20),mat(T,c));m.position.set(x,y,z);m.scale.set(...scale);m.name=name;g.add(m);return m;}
function box(g,T,x,y,z,sx,sy,sz,c,name=''){let m=new T.Mesh(new T.BoxGeometry(sx,sy,sz),mat(T,c));m.position.set(x,y,z);m.name=name;g.add(m);return m;}
function rod(g,T,a,b,r,c,name=''){let p=new T.Vector3(...a),q=new T.Vector3(...b),v=q.clone().sub(p),m=new T.Mesh(new T.CylinderGeometry(r,r,v.length(),16),mat(T,c));m.position.copy(p.add(q).multiplyScalar(.5));m.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),v.normalize());m.name=name;g.add(m);return m;}
function antibody(g,T,x,y,z,s=.4,payload=false){rod(g,T,[x,y-s,z],[x,y,z],s*.09,0xe8a796,'antibody');for(let sign of[-1,1])rod(g,T,[x,y,z],[x+sign*s*.65,y+s*.55,z],s*.09,0xe8a796,'binding-arm');if(payload)ball(g,T,x,y-s,z,s*.3,0xe8cc97,[1,1,1],'linked-payload');}
function cell(g,T,x,y,r=.55,hybrid=false){ball(g,T,x,y,0,r,hybrid?0xa9bfac:0xa4bec0,[1,1,.75],hybrid?'hybridoma':'source-cell');ball(g,T,x-.12,y,.4*r,r*.28,0xad8ea5,[1,1,.7],'nucleus');if(hybrid)ball(g,T,x+.18,y,.4*r,r*.22,0xc7a58e,[1,1,.7],'fusion-symbol');}
function leaf(g,T,x=0,y=0,state='healthy',scale=1){let shape=new T.Shape();shape.moveTo(0,-1.2);shape.bezierCurveTo(-1.25,-.1,-.8,1.1,0,1.3);shape.bezierCurveTo(.8,1.1,1.25,-.1,0,-1.2);let m=new T.Mesh(new T.ExtrudeGeometry(shape,{depth:.08,bevelEnabled:true,bevelSize:.03,bevelThickness:.025,bevelSegments:2}),mat(T,['yellow','magnesium-low'].includes(state)?0xd7c68c:0x91b09b));m.position.set(x,y,0);m.scale.setScalar(scale);m.name='leaf-surface';g.add(m);rod(g,T,[x,y-1.15*scale,.15],[x,y+1.2*scale,.15],.025*scale,0xd0cbb0,'leaf-vein');if(['spots','blackspot','tmv','rot'].includes(state))for(let i=0;i<8;i++)ball(g,T,x+Math.sin(i*2)*.47*scale,y-.7*scale+(i%4)*.4*scale,.14,.13*scale,state==='tmv'?0xe2cc96:0x745f62,[1,.9,.13],'damaged-area');if(state==='malformed'){m.scale.x=.45;let p=m.geometry.attributes.position;for(let i=0;i<p.count;i++)p.setZ(i,p.getZ(i)+Math.sin(p.getY(i)*3)*.2);p.needsUpdate=true;m.geometry.computeVertexNormals();}return m;}
function insect(g,T,x,y,z=0,s=.35){ball(g,T,x,y,z,s,0xb7b696,[.8,1.3,.7],'insect-pest');ball(g,T,x,y+s*1.3,z,s*.45,0xc8c2a1);for(let side of[-1,1])for(let i=0;i<3;i++)rod(g,T,[x+side*s*.5,y+(i-1)*s*.5,z],[x+side*s*1.5,y+(i-1)*s*.8,z],.015,0xd4cfaf,'insect-leg');}
function plant(g,T,state='complete'){let short=state==='nitrate-low'||state==='stunted',height=short?.9:2.7;rod(g,T,[0,-1.4,0],[0,-1.4+height,0],.06,0x96ac8d,'stem');for(let i=0;i<4;i++){let sign=i%2?1:-1,y=-1.1+i*height*.23,m=leaf(g,T,sign*.55,y,state,short?.28:.42);m.rotation.z=-sign*.45;}if(state==='growth')ball(g,T,.08,-.15,.2,.3,0xbaa68b,[1,1,.6],'unusual-growth');if(['aphid','pests'].includes(state))for(let i=0;i<3;i++)insect(g,T,-.4+i*.4,.5,.3,.12);}
export function buildSpecial(g,T,w={}){let kind=w.kind||'fusion',s=w.state||'parents',r=w.revealed!==false;
if(kind==='fusion'){let step=w.step??(s==='purify'?5:s==='clone'?4:s==='hybridoma'?2:s==='tumour'?0:s==='lymphocyte'?1:0);if(step>=5){for(let i=0;i<12;i++)antibody(g,T,-1.25+(i%4)*.8,-.7+Math.floor(i/4)*.65,.2,.25);box(g,T,0,-1.55,0,3.7,.12,.9,0xb4c8c7,'collection-tray');}else if(step===4){for(let i=0;i<6;i++){let x=-1.1+(i%3)*1.1,y=-.6+Math.floor(i/3)*1.2;cell(g,T,x,y,.42,true);antibody(g,T,x+.3,y+.4,.3,.17);}}else if(step>=2){cell(g,T,0,0,.85,true);antibody(g,T,1.2,.25,.3,.4);if(step===3){let ring=new T.Mesh(new T.TorusGeometry(1,.035,10,64),mat(T,0xf1d6a3));ring.name='selected-clone';g.add(ring);}}else{cell(g,T,-1,0,.65,false);cell(g,T,1,0,.65,false);if(step===1||s==='lymphocyte')antibody(g,T,-1,.9,.2,.3);}}
else if(kind==='binding'){let match=s!=='nonmatch',bound=r&&match;cell(g,T,.85,0,.75);let target=new T.Mesh(match?new T.BoxGeometry(.2,.2,.16):new T.SphereGeometry(.13,20,12),mat(T,0xe6c493));target.position.set(.2,.25,.5);target.name='target-site';g.add(target);let x=bound?-.1:-1;antibody(g,T,x,-.02,.5,.45,['payload','harm'].includes(s));if(s==='fluorescent'&&r)for(let i=0;i<7;i++)ball(g,T,.8+Math.sin(i)*.8,Math.cos(i)*.8,.1,.07,0xf3dfac,[1,1,1],'fluorescent-label');if(s==='harm'&&r)rod(g,T,[.3,-.7,.7],[1.4,.7,.7],.035,0xe3a08c,'adverse-effect-marker');}
else if(kind==='assay'){let step=w.step??3,condition=w.condition||s,b=assayBands(condition,step);box(g,T,0,0,-.1,4.2,1.25,.25,0xd8d2c2,'assay-casing');box(g,T,0,0,.05,3.7,.65,.12,0xf0e7d5,'membrane');box(g,T,-1.55,0,.14,.5,.65,.08,0xc4b6a6,'sample-pad');if(b.test)box(g,T,.35,0,.17,.075,.62,.08,0xd68f82,'test-band');if(b.control)box(g,T,1.05,0,.17,.075,.62,.08,0x9b7d8c,'control-band');for(let i=0;i<4;i++)ball(g,T,-1.65+Math.min(step,2)*.65+i*.15,.1*(i%2?1:-1),.25,.06,0xc99681,[1,1,.4],'labelled-material');}
else if(kind==='nutrient'||kind==='plant'){plant(g,T,r?s:'complete');if(s==='bacterial')for(let i=0;i<6;i++)ball(g,T,-.8+i*.3,.5,.6,.08,0xc7b691,[1.4,.7,.7],'bacterial-symbol');}
else if(kind==='symptoms'){if(['spots','rot','malformed','yellow'].includes(s))leaf(g,T,0,0,s);else plant(g,T,s);}
else if(kind==='barrier'){if(['bark','shed'].includes(s)){let trunk=new T.Mesh(new T.CylinderGeometry(.7,.75,3,48),mat(T,0x9b8272));trunk.name='stem-core';g.add(trunk);for(let i=0;i<8;i++){let a=i*Math.PI/4,x=Math.sin(a)*.78,z=Math.cos(a)*.78,peel=s==='shed'&&r&&i<2;let b=box(g,T,x+(peel?.8:0),peel?-.3:0,z+(peel?.5:0),.45,2.8,.16,0xb3987d,peel?'shed-bark':'bark-layer');b.rotation.y=a;if(i<2)ball(g,T,x+(peel?.8:0),.7,z+.2+(peel?.5:0),.08,0xc9bba0,[1,1,1],'surface-organism');}}else{for(let i=0;i<6;i++)box(g,T,-1.2+(i%3)*1.2,-.5+Math.floor(i/3)*.85,0,1.05,.7,.5,0xa7bfae,'epidermal-cell');if(s==='cuticle')box(g,T,0,0,.4,3.7,1.8,.12,0xd1c7a4,'waxy-cuticle');else for(let i=0;i<6;i++){let frame=new T.LineSegments(new T.EdgesGeometry(new T.BoxGeometry(1.09,.74,.55)),new T.LineBasicMaterial({color:0xe6d7b0}));frame.position.set(-1.2+(i%3)*1.2,-.5+Math.floor(i/3)*.85,0);frame.name='cellulose-wall';g.add(frame);}}}
else if(kind==='chemical'){leaf(g,T,0,0,'healthy',.8);if(s==='antibacterial'){for(let i=0;i<(r?2:7);i++)ball(g,T,-1.2+i*.4,.7,.5,.12,0xc8c0a0,[1.3,.7,.8],'bacterial-symbol');for(let i=0;i<5;i++)ball(g,T,-.6+i*.3,-.6,.3,.06,0xe3c296,[1,1,1],'antibacterial-symbol');}else{insect(g,T,r?1.8:.7,.4,.3,.25);for(let i=0;i<4;i++)ball(g,T,-.5+i*.35,.2,.25,.07,0xd9b69f,[1,1,1],'deterrent-symbol');}}
else if(kind==='mechanical'){if(s==='thorns'){rod(g,T,[0,-1.5,0],[0,1.5,0],.1,0x9caa89);for(let i=0;i<7;i++){let m=new T.Mesh(new T.ConeGeometry(.14,.55,20),mat(T,0xd0ba9a));m.rotation.z=(i%2?1:-1)*Math.PI/2;m.position.set(i%2?.3:-.3,-1.2+i*.4,0);m.name='thorn';g.add(m);}}else if(['open','fold'].includes(s)){rod(g,T,[0,-1.4,0],[0,1.3,0],.04,0x9bae8f);for(let side of[-1,1])for(let i=0;i<4;i++){let pivot=new T.Group();pivot.position.set(0,-.7+i*.5,0);pivot.rotation.y=s==='fold'&&r?side*1.15:0;pivot.rotation.z=side*(s==='fold'&&r?-.7:.4);g.add(pivot);leaf(pivot,T,side*.5,0,'healthy',.3);pivot.name='touch-leaflet';}}else{leaf(g,T,0,0);if(s==='hairs')for(let i=0;i<20;i++)rod(g,T,[Math.sin(i*2)*.6,-.8+(i%6)*.3,.2],[Math.sin(i*2)*.6,-.8+(i%6)*.3,.55],.016,0xecd9b9,'leaf-hair');if(s==='mimicry')for(let i=0;i<6;i++)ball(g,T,-.4+(i%3)*.35,-.45+Math.floor(i/3)*.55,.2,.1,0xe9d9aa,[1,.75,.3],'egg-like-mark');insect(g,T,s==='mimicry'&&r?1.7:.8,.55,.25,.2);}}else{for(let i=0;i<3;i++)box(g,T,-1.2+i*1.2,0,0,.85,1.1,.15,[0xa5bcb1,0xc3b19e,0xc0bcb2][i],'evidence-source');}
}
